  const despues = mediana(minutos);
  return {
    antes_minutos: antes,
    despues_minutos: despues === null ? null : metRedondeo(despues, 1),
    mejora_pct: antes && despues !== null ? metRedondeo(((antes - despues) / antes) * 100, 1) : null,
    conversaciones_medidas: minutos.length,
